package io.github.astelev.around_planet.compat;
/** Pondus updates its own cache. Without it, change only this block's native mass contribution. */
public final class RocketMassChange {
 public static void changed(net.minecraft.world.level.block.entity.BlockEntity be,double delta){if(delta==0||be.getLevel()==null||be.getLevel().isClientSide||io.github.astelev.around_planet.fuel.FuelMassBridge.pondus())return;var body=dev.ryanhcode.sable.Sable.HELPER.getContaining(be.getLevel(),be.getBlockPos());if(body instanceof dev.ryanhcode.sable.sublevel.ServerSubLevel ship&&!ship.isRemoved())ship.getSelfMassTracker().addBlockMass(be.getLevel(),be.getBlockState(),be.getBlockPos(),delta,dev.ryanhcode.sable.physics.config.block_properties.PhysicsBlockPropertyHelper.getInertia(be.getLevel(),be.getBlockPos(),be.getBlockState()));}
 public static void assembled(dev.ryanhcode.sable.sublevel.ServerSubLevel ship,io.github.astelev.around_planet.propulsion.PropulsionBlockEntity be){if(io.github.astelev.around_planet.fuel.FuelMassBridge.pondus()){try{Class.forName("org.fractalinteractive.ci.pondus_inventory_fi.listener.InventoryChangeListener").getMethod("onInventoryChanged",dev.ryanhcode.sable.sublevel.ServerSubLevel.class,net.minecraft.core.BlockPos.class,net.minecraft.world.level.block.entity.BlockEntity.class).invoke(null,ship,be.getBlockPos(),be);}catch(ReflectiveOperationException e){throw new IllegalStateException("Cannot synchronize rocket inventory with Pondus",e);}}else changed(be,io.github.astelev.around_planet.fuel.FuelMassBridge.mass(be));ship.updateMergedMassData(0);}
 private RocketMassChange(){}
}
